window.CHUJI_DATA_14 = [{"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 1, "type": "reading", "en": "What would you do if you were a millionaire?", "zh": "你若是百万富翁，你会怎么做？", "audio": "chuji_l131_01.mp3", "localAudio": "audio_chunks/chuji_l131_01.mp3", "b64": "", "src": "chuji"}, {"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 2, "type": "reading", "en": "Many people would buy a house or travel the world.", "zh": "许多人会买幢房子或到世界各地旅行。", "audio": "chuji_l131_02.mp3", "localAudio": "audio_chunks/chuji_l131_02.mp3", "b64": "", "src": "chuji"}, {"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 3, "type": "reading", "en": "As for me, I would start a school.", "zh": "至于我，我会办一所学校。", "audio": "chuji_l131_03.mp3", "localAudio": "audio_chunks/chuji_l131_03.mp3", "b64": "", "src": "chuji"}, {"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 4, "type": "reading", "en": "If I had a school, I would be able to educate many children and teach them right from wrong.", "zh": "如果我有一所学校，我就可以教育许多小孩并且教他们分辨是非。", "audio": "chuji_l131_04.mp3", "localAudio": "audio_chunks/chuji_l131_04.mp3", "b64": "", "src": "chuji"}, {"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 5, "type": "reading", "en": "Anyone will tell you that children are a country's future.", "zh": "每个人都会告诉你孩子是国家的未来。", "audio": "chuji_l131_05.mp3", "localAudio": "audio_chunks/chuji_l131_05.mp3", "b64": "", "src": "chuji"}, {"l": 431, "lt": "Lesson 131 If I Were a Millionaire 假如我是百万富翁", "i": 6, "type": "reading", "en": "If my dream comes true, I will be very happy because I will be doing my country a good service.", "zh": "我的梦想若实现的话，我将会很高兴，因为我将对国家大有贡献。", "audio": "chuji_l131_06.mp3", "localAudio": "audio_chunks/chuji_l131_06.mp3", "b64": "", "src": "chuji"}, {"l": 432, "lt": "Lesson 132 A Good Citizen 好公民", "i": 1, "type": "dialog", "en": "How can I be a good citizen?", "zh": "我要如何成为一个好公民？", "audio": "chuji_l132_01.mp3", "localAudio": "audio_chunks/chuji_l132_01.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 432, "lt": "Lesson 132 A Good Citizen 好公民", "i": 2, "type": "dialog", "en": "Well, always ask yourself what you can do for your country, and not what your country can do for you.", "zh": "嗯，要问自己能为国家做什么，而不是国家能为你做什么。", "audio": "chuji_l132_02.mp3", "localAudio": "audio_chunks/chuji_l132_02.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 432, "lt": "Lesson 132 A Good Citizen 好公民", "i": 3, "type": "dialog", "en": "Wow! That was very well said.", "zh": "哇！说得真好。", "audio": "chuji_l132_03.mp3", "localAudio": "audio_chunks/chuji_l132_03.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 1, "type": "reading", "en": "Examinations are an important part of every student's life.", "zh": "考试是每位学生生活中重要的一部分。", "audio": "chuji_l133_01.mp3", "localAudio": "audio_chunks/chuji_l133_01.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 2, "type": "reading", "en": "Students must, therefore, know how to deal with them.", "zh": "因此，学生必须知道如何应付考试。", "audio": "chuji_l133_02.mp3", "localAudio": "audio_chunks/chuji_l133_02.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 3, "type": "reading", "en": "There are three important things a student must do to get ready for an exam.", "zh": "学生在准备考试时有三件大事必须做。", "audio": "chuji_l133_03.mp3", "localAudio": "audio_chunks/chuji_l133_03.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 4, "type": "reading", "en": "First, he must work out a study plan.", "zh": "首先，他必须制定一个学习计划。", "audio": "chuji_l133_04.mp3", "localAudio": "audio_chunks/chuji_l133_04.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 5, "type": "reading", "en": "Second, he must always keep his mind fresh by setting aside some time for exercise.", "zh": "其次，他必须拨出时间来运动以保持头脑清楚。", "audio": "chuji_l133_05.mp3", "localAudio": "audio_chunks/chuji_l133_05.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 6, "type": "reading", "en": "And last but not least, he must review what he has studied at least three times.", "zh": "最后也是相当重要的就是，他必须把念过的书至少复习三遍。", "audio": "chuji_l133_06.mp3", "localAudio": "audio_chunks/chuji_l133_06.mp3", "b64": "", "src": "chuji"}, {"l": 433, "lt": "Lesson 133 Dealing with Exams 应付考试", "i": 7, "type": "reading", "en": "After all, success can only be achieved through hard work.", "zh": "毕竟，唯有经由努力才能获致成功。", "audio": "chuji_l133_07.mp3", "localAudio": "audio_chunks/chuji_l133_07.mp3", "b64": "", "src": "chuji"}, {"l": 434, "lt": "Lesson 134 Guess What? 你猜怎么了？", "i": 1, "type": "dialog", "en": "Guess what, Mom?", "zh": "妈，你猜怎么了？", "audio": "chuji_l134_01.mp3", "localAudio": "audio_chunks/chuji_l134_01.mp3", "b64": "", "src": "chuji", "speaker": "Mack", "note": "说话人: Mack"}, {"l": 434, "lt": "Lesson 134 Guess What? 你猜怎么了？", "i": 2, "type": "dialog", "en": "What?", "zh": "怎么了？", "audio": "chuji_l134_02.mp3", "localAudio": "audio_chunks/chuji_l134_02.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 434, "lt": "Lesson 134 Guess What? 你猜怎么了？", "i": 3, "type": "dialog", "en": "I got through the exams with flying colors.", "zh": "我考试高分过关。", "audio": "chuji_l134_03.mp3", "localAudio": "audio_chunks/chuji_l134_03.mp3", "b64": "", "src": "chuji", "speaker": "Mack", "note": "说话人: Mack"}, {"l": 434, "lt": "Lesson 134 Guess What? 你猜怎么了？", "i": 4, "type": "dialog", "en": "Well done, son! I'm really proud of you.", "zh": "儿子，干得好，我真以你为荣。", "audio": "chuji_l134_04.mp3", "localAudio": "audio_chunks/chuji_l134_04.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 1, "type": "reading", "en": "Many people put off until tomorrow what they can do today.", "zh": "许多人把今天能做的事推到明日。", "audio": "chuji_l135_01.mp3", "localAudio": "audio_chunks/chuji_l135_01.mp3", "b64": "", "src": "chuji"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 2, "type": "reading", "en": "They always look for excuses to postpone doing something.", "zh": "他们总是找借口拖延做事。", "audio": "chuji_l135_02.mp3", "localAudio": "audio_chunks/chuji_l135_02.mp3", "b64": "", "src": "chuji"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 3, "type": "reading", "en": "In the end, it never gets done.", "zh": "到头来事情总是没做完。", "audio": "chuji_l135_03.mp3", "localAudio": "audio_chunks/chuji_l135_03.mp3", "b64": "", "src": "chuji"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 4, "type": "reading", "en": "If we leave things undone, we will eventually worry.", "zh": "我们若没把事情做完，终究还是会操心。", "audio": "chuji_l135_04.mp3", "localAudio": "audio_chunks/chuji_l135_04.mp3", "b64": "", "src": "chuji"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 5, "type": "reading", "en": "This will then cause unnecessary stress.", "zh": "而这样会造成不必要的压力。", "audio": "chuji_l135_05.mp3", "localAudio": "audio_chunks/chuji_l135_05.mp3", "b64": "", "src": "chuji"}, {"l": 435, "lt": "Lesson 135 Just Do It 即说即做", "i": 6, "type": "reading", "en": "Therefore, if you have this bad habit, it's best to get rid of it and do things as soon as possible.", "zh": "因此，如果你有这种坏习惯的话，最好是戒掉它并且尽快把事情做好。", "audio": "chuji_l135_06.mp3", "localAudio": "audio_chunks/chuji_l135_06.mp3", "b64": "", "src": "chuji"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 1, "type": "dialog", "en": "Hi, Lisa. Are you free this Saturday?", "zh": "嗨，丽莎。这个星期六你有空吗？", "audio": "chuji_l136_01.mp3", "localAudio": "audio_chunks/chuji_l136_01.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 2, "type": "dialog", "en": "Yes. Why?", "zh": "有啊。干嘛？", "audio": "chuji_l136_02.mp3", "localAudio": "audio_chunks/chuji_l136_02.mp3", "b64": "", "src": "chuji", "speaker": "Lisa", "note": "说话人: Lisa"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 3, "type": "dialog", "en": "Would you like to go to a party with me?", "zh": "你要不要和我一块去参加派对？", "audio": "chuji_l136_03.mp3", "localAudio": "audio_chunks/chuji_l136_03.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 4, "type": "dialog", "en": "Okay. Will you pick me up at my place?", "zh": "好啊。你会到我家来接我吗？", "audio": "chuji_l136_04.mp3", "localAudio": "audio_chunks/chuji_l136_04.mp3", "b64": "", "src": "chuji", "speaker": "Lisa", "note": "说话人: Lisa"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 5, "type": "dialog", "en": "Sure. Is 8 o'clock all right?", "zh": "当然。八点钟可以吗？", "audio": "chuji_l136_05.mp3", "localAudio": "audio_chunks/chuji_l136_05.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 436, "lt": "Lesson 136 Are You Free? 你有空吗？", "i": 6, "type": "dialog", "en": "That'll be fine. See you then.", "zh": "可以。届时见。", "audio": "chuji_l136_06.mp3", "localAudio": "audio_chunks/chuji_l136_06.mp3", "b64": "", "src": "chuji", "speaker": "Lisa", "note": "说话人: Lisa"}, {"l": 437, "lt": "Lesson 137 Van Gogh 梵高", "i": 1, "type": "reading", "en": "It cannot be denied that Van Gogh was a great artist.", "zh": "不可否认，梵高是位伟大的艺术家。", "audio": "chuji_l137_01.mp3", "localAudio": "audio_chunks/chuji_l137_01.mp3", "b64": "", "src": "chuji"}, {"l": 437, "lt": "Lesson 137 Van Gogh 梵高", "i": 2, "type": "reading", "en": "However, he was considered an outcast by other artists of his time.", "zh": "不过，他那个时代的其他艺术家都认为他是个被社会所排斥的人。", "audio": "chuji_l137_02.mp3", "localAudio": "audio_chunks/chuji_l137_02.mp3", "b64": "", "src": "chuji"}, {"l": 437, "lt": "Lesson 137 Van Gogh 梵高", "i": 3, "type": "reading", "en": "Many of his most famous paintings were painted at a time when he was isolated by society.", "zh": "他许多最有名的画都是在他被社会孤立的时候所画的。", "audio": "chuji_l137_03.mp3", "localAudio": "audio_chunks/chuji_l137_03.mp3", "b64": "", "src": "chuji"}, {"l": 437, "lt": "Lesson 137 Van Gogh 梵高", "i": 4, "type": "reading", "en": "Today these paintings are admired as masterpieces, and are sold for large sums of money.", "zh": "如今这些画都被尊为杰作，而且以巨额金钱售出。", "audio": "chuji_l137_04.mp3", "localAudio": "audio_chunks/chuji_l137_04.mp3", "b64": "", "src": "chuji"}, {"l": 437, "lt": "Lesson 137 Van Gogh 梵高", "i": 5, "type": "reading", "en": "Clearly, it was Van Gogh's destiny to be a painter.", "zh": "显然，梵高命中注定要做个画家。", "audio": "chuji_l137_05.mp3", "localAudio": "audio_chunks/chuji_l137_05.mp3", "b64": "", "src": "chuji"}, {"l": 438, "lt": "Lesson 138 You're Beautiful 你很漂亮", "i": 1, "type": "dialog", "en": "May I take your photograph, Jane?", "zh": "简，我可以帮你照张相吗？", "audio": "chuji_l138_01.mp3", "localAudio": "audio_chunks/chuji_l138_01.mp3", "b64": "", "src": "chuji", "speaker": "Eric", "note": "说话人: Eric"}, {"l": 438, "lt": "Lesson 138 You're Beautiful 你很漂亮", "i": 2, "type": "dialog", "en": "Please don't.", "zh": "请不要。", "audio": "chuji_l138_02.mp3", "localAudio": "audio_chunks/chuji_l138_02.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 438, "lt": "Lesson 138 You're Beautiful 你很漂亮", "i": 3, "type": "dialog", "en": "Why not? You're beautiful.", "zh": "为什么不要？你很漂亮啊。", "audio": "chuji_l138_03.mp3", "localAudio": "audio_chunks/chuji_l138_03.mp3", "b64": "", "src": "chuji", "speaker": "Eric", "note": "说话人: Eric"}, {"l": 438, "lt": "Lesson 138 You're Beautiful 你很漂亮", "i": 4, "type": "dialog", "en": "Well, I do not consider myself photogenic.", "zh": "咂，我不认为自己很上相。", "audio": "chuji_l138_04.mp3", "localAudio": "audio_chunks/chuji_l138_04.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 439, "lt": "Lesson 139 Don't Be Shy 不要害羞", "i": 1, "type": "reading", "en": "Our English teacher often says that we should not be afraid to make mistakes.", "zh": "我们的英文老师常说我们应该不要怕犯错。", "audio": "chuji_l139_01.mp3", "localAudio": "audio_chunks/chuji_l139_01.mp3", "b64": "", "src": "chuji"}, {"l": 439, "lt": "Lesson 139 Don't Be Shy 不要害羞", "i": 2, "type": "reading", "en": "She also says that people can learn from their mistakes.", "zh": "她也说人可以从错误中学习。", "audio": "chuji_l139_02.mp3", "localAudio": "audio_chunks/chuji_l139_02.mp3", "b64": "", "src": "chuji"}, {"l": 439, "lt": "Lesson 139 Don't Be Shy 不要害羞", "i": 3, "type": "reading", "en": "Therefore, she tells us that we shouldn't be shy when we speak English.", "zh": "因此，她告诉我们说英文时不要害羞。", "audio": "chuji_l139_03.mp3", "localAudio": "audio_chunks/chuji_l139_03.mp3", "b64": "", "src": "chuji"}, {"l": 439, "lt": "Lesson 139 Don't Be Shy 不要害羞", "i": 4, "type": "reading", "en": "I believe what she says is right, but there is one thing that I don't understand.", "zh": "我相信她所说的是正确的，但有一件事我不明白。", "audio": "chuji_l139_04.mp3", "localAudio": "audio_chunks/chuji_l139_04.mp3", "b64": "", "src": "chuji"}, {"l": 439, "lt": "Lesson 139 Don't Be Shy 不要害羞", "i": 5, "type": "reading", "en": "Every time we speak in class, she tells us to shut up!", "zh": "每次我们在课堂上讲话，她就叫我们闭嘴！", "audio": "chuji_l139_05.mp3", "localAudio": "audio_chunks/chuji_l139_05.mp3", "b64": "", "src": "chuji"}, {"l": 440, "lt": "Lesson 140 What's New? 近况如何？", "i": 1, "type": "dialog", "en": "Hi, Kelly. What's new?", "zh": "嗨，凯莉。有什么新鲜事吗？", "audio": "chuji_l140_01.mp3", "localAudio": "audio_chunks/chuji_l140_01.mp3", "b64": "", "src": "chuji", "speaker": "Dan", "note": "说话人: Dan"}, {"l": 440, "lt": "Lesson 140 What's New? 近况如何？", "i": 2, "type": "dialog", "en": "My father told us that we'll soon be moving.", "zh": "我父亲告诉我们说我们很快就要搬家了。", "audio": "chuji_l140_02.mp3", "localAudio": "audio_chunks/chuji_l140_02.mp3", "b64": "", "src": "chuji", "speaker": "Kelly", "note": "说话人: Kelly"}, {"l": 440, "lt": "Lesson 140 What's New? 近况如何？", "i": 3, "type": "dialog", "en": "That's awful.", "zh": "那太糟了。", "audio": "chuji_l140_03.mp3", "localAudio": "audio_chunks/chuji_l140_03.mp3", "b64": "", "src": "chuji", "speaker": "Dan", "note": "说话人: Dan"}, {"l": 440, "lt": "Lesson 140 What's New? 近况如何？", "i": 4, "type": "dialog", "en": "Why?", "zh": "为什么？", "audio": "chuji_l140_04.mp3", "localAudio": "audio_chunks/chuji_l140_04.mp3", "b64": "", "src": "chuji", "speaker": "Kelly", "note": "说话人: Kelly"}, {"l": 440, "lt": "Lesson 140 What's New? 近况如何？", "i": 5, "type": "dialog", "en": "I won't have anyone to make fun of anymore.", "zh": "我就没有人可以取笑了。", "audio": "chuji_l140_05.mp3", "localAudio": "audio_chunks/chuji_l140_05.mp3", "b64": "", "src": "chuji", "speaker": "Dan", "note": "说话人: Dan"}];